import React, { useState } from 'react';

// Create the Tooltip component here
const Tooltip = () => {
  // Initialize tooltip visibility state here
  const [isVisible, setIsVisible] = useState(false);

  // Create mouse event handlers here
  const handleMouseEnter = () => setIsVisible(true);
  const handleMouseLeave = () => setIsVisible(false);

  return (
    <div>
      {/* Add trigger button here */}
      <button 
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        Hover over me
      </button>

      {/* Add conditional tooltip rendering here */}
      {isVisible && (
        <div>
          This is a tooltip
        </div>
      )}
    </div>
  );
};

